INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(119477, 'ruRU', '', 'Ты вернулся! Я думал, мой конец наконец настал.', 24330),
(119478, 'ruRU', '', 'Никогда, друг мой. Свет стоит вместе.', 24330),
(119480, 'ruRU', '', 'Аратор, ты всё ещё жив?', 24330),
(119482, 'ruRU', '', 'Тебе следует вернуться к порталу. Верховный лорд и я позаботимся об остальном.', 24330),
(119485, 'ruRU', '', 'Я пойду вперёд и помогу остальным. Мы выберемся отсюда вместе, сестра.', 24330),
(119494, 'ruRU', '', 'Ты не покинешь моего поля зрения, пока не назначат советника. Обещай мне!', 24330),
(119496, 'ruRU', '', 'Благодарю. Дай знать Ли''лет, что я на её стороне.', 24330),
(119498, 'ruRU', '', 'Конечно! Но вся твердыня всё ещё кишит Ночнорождёнными.', 24330),
(119509, 'ruRU', '', 'Elun''orin torel!', 24330),
(119522, 'ruRU', '', 'Ситуация в Штормграде хуже, чем мы думали. У нас есть план разоблачить Детерока как самозванца, которым он является. Мастер Шо?', 24330),
(119529, 'ruRU', '', 'Благодарю, мастер Шо. Вот план, Некоронованные. Все за?', 24330),
(119534, 'ruRU', '', 'Отправьте подкрепление к Южным воротам!', 24330),
(119545, 'ruRU', '', 'Просто сделай это уже! Я предпочту умереть, чем провести ещё один день, живя жизнью, построенной вокруг твоих искривлённых убеждений!', 24330),
(119546, 'ruRU', '', 'Я больше не принимаю их имени и их ценностей.', 24330),
(119547, 'ruRU', '', 'Я хочу помочь своим собратьям-жрецам в их борьбе против Пылающего Легиона.', 24330),
(119550, 'ruRU', '', 'Ты дал мне шанс искупить себя, и я посвящу этому свою жизнь.', 24330),
(119551, 'ruRU', '', 'Тени поглотят тебя!', 24330),
(119552, 'ruRU', '', 'Тени на твоей стороне, если они тебе когда-нибудь понадобятся.', 24330),
(119555, 'ruRU', '', 'Из Аркопути уже недели сочится гнилостная слизь. Найди источник и перекрой его!', 24330),
(119556, 'ruRU', '', 'Я работал с Апони Светлая Грива и лидером её ордена. Мы перевели кодекс, подробно описывающий планы Легиона установить точку вторжения у Врат Демонического Пламени.', 24330),
(119557, 'ruRU', '', 'Я хотел бы взять небольшую группу жрецов, чтобы сопровождать паладинов в поисках по этому демоническому миру. Если повелитель ужаса там, мы его найдём.', 24330),
(119560, 'ruRU', '', 'Пусть Свет направляет твой путь.', 26972),
(119561, 'ruRU', '', 'Ты не будешь одинок в этом путешествии.', 24330),
(119562, 'ruRU', '', 'Свободная мана Аркопути породила чудовище! Разберись с ним, прежде чем оно станет ещё большей угрозой!', 24330),
(119563, 'ruRU', '', 'Чародей Наран до сих пор не вернулся из Аркопути. Узнай, что с ним случилось, и доложи мне.', 24330),
(119564, 'ruRU', '', 'Мой дух един с Пустотой!', 24330),
(119565, 'ruRU', '', 'Найди краеугольный камень, что некогда питал эти залы. Мана, что он хранит, поможет нашему делу!', 24330),
(119566, 'ruRU', '', 'Благодарю, жрец. Тяжесть тьмы снята.', 24330),
(119567, 'ruRU', '', 'Чума бесчинствует в Аркопути. Очисти заразу, прежде чем она распространится дальше!', 24330),
(119578, 'ruRU', '', 'Благодаря тебе Аркопуть на шаг ближе к своей прежней славе.', 24330),
(119579, 'ruRU', '', 'Я никогда не верил, что змеи могут стать такими огромными! Ты спас нас всех.', 24330),
(119580, 'ruRU', '', 'Мы потеряли бы чародея Нарана без твоей помощи. Благодарю. Я у тебя в долгу.', 24330),
(119581, 'ruRU', '', 'Этот краеугольный камень обеспечит наш успех против Магистрикс. Твои усилия не будут забыты.', 24330),
(119582, 'ruRU', '', 'Благодаря тебе чума не распространится дальше.', 24330),
(119630, 'ruRU', '', 'Я проводил исследование для Генерала-рейнджера Ветрокрылой, когда разразился весь этот ад.$b$bЧто тебе нужно?', 24330),
(119634, 'ruRU', '', 'Я читал про книгу, написанную мастером-ремесленником, что подробно рассказывала о Пеплосерде.\n\nКажется, большинство экземпляров были потеряны давно, их потрёпанные страницы развеяны по ветру.\n\nИнтересно, не завалялась ли она ещё где-то? Уверен, мы могли бы узнать кое-что, коли сумели б собрать её обратно!', 24330),
(119635, 'ruRU', '', 'Я открою её немедленно. Затем мне нужно сообщить генералу-рейнджеру о своих находках. Удачи!', 24330),
(119639, 'ruRU', '', '<Эльда осторожно перебирает страницы, её глаза быстро скользят по потрёпанному тексту.>\n\nКлянусь Светом, Верховный лорд — думаю, ты прав! Это должна быть она!\n\nЯ смогу собрать её обратно — дай мне всего минутку!', 24330),
(119647, 'ruRU', '', 'Это займёт всего минутку-другую. Ох, как это увлекательно!', 24330),
(119649, 'ruRU', '', 'Я сделаю копию для наших архивов, чтобы ты мог оставить готовую книгу себе, Верховный лорд.', 24330);
